+  startAt: Date;
+  endAt: Date;
+  status: string;
+  items?: Array<{ serviceId: string }>;
+}): NotifiableAppointmentFields {
+  return {
+    startAt: row.startAt,
+    endAt: row.endAt,
+    status: row.status,
+    serviceIds: (row.items ?? []).map((item) => item.serviceId),
+  };
