+  before: string[] | undefined,
+  after: string[],
+): boolean {
+  if (!before) return false;
+  const previous = [...new Set(before)].sort();
+  const current = [...new Set(after)].sort();
+  return (
+    previous.length === current.length &&
+    previous.every((serviceId, index) => serviceId === current[index])
+  );
